<?php
require 'config.php';require_login();$uid=(int)$_SESSION['user_id'];ai_refresh($pdo,$uid);
$status=input_string('status',$_GET)?:'ACTIVE';$search=mb_substr(input_string('q',$_GET),0,180);$category=(int)input_string('category',$_GET);$sort=input_string('sort',$_GET)?:'ai';
if(!in_array($sort,['ai','due','newest'],true))$sort='ai';
$sql='SELECT t.*,c.category_name FROM tasks t LEFT JOIN categories c ON c.category_id=t.category_id WHERE t.user_id=?';$args=[$uid];
if($status==='ACTIVE')$sql.=" AND t.status IN('PENDING','IN_PROGRESS')";
elseif($status==='OVERDUE')$sql.=" AND t.status IN('PENDING','IN_PROGRESS') AND t.due_at<NOW()";
elseif(in_array($status,['PENDING','IN_PROGRESS','COMPLETED','CANCELLED'],true)){$sql.=' AND t.status=?';$args[]=$status;}
elseif($status!=='ALL'){$status='ACTIVE';$sql.=" AND t.status IN('PENDING','IN_PROGRESS')";}
if($search!==''){$sql.=' AND (t.title LIKE ? OR t.description LIKE ?)';$args[]='%'.$search.'%';$args[]='%'.$search.'%';}
if($category>0){$sql.=' AND t.category_id=?';$args[]=$category;}
$sql.=$sort==='due'?' ORDER BY t.due_at IS NULL,t.due_at,t.task_id DESC':($sort==='newest'?' ORDER BY t.created_at DESC,t.task_id DESC':' ORDER BY t.ai_priority_score DESC,t.due_at IS NULL,t.due_at,t.task_id');
$sql.=' LIMIT 250';$q=$pdo->prepare($sql);$q->execute($args);$tasks=$q->fetchAll();
$q=$pdo->prepare('SELECT category_id,category_name FROM categories WHERE user_id IS NULL OR user_id=? ORDER BY category_name');$q->execute([$uid]);$categories=$q->fetchAll();
$returnFilters=['return_status'=>$status,'return_q'=>$search,'return_category'=>max(0,$category),'return_sort'=>$sort];
$pageTitle='My tasks';include 'includes/header.php';?>
<main id="main-content" class="container"><div class="page-heading"><div><p class="eyebrow">A CLEARER PATH THROUGH YOUR DAY</p><h1>My tasks</h1><p class="muted">Everything on your mind, organised in one place.</p></div><a class="btn primary" href="add_task.php"><?=icon('plus')?> Create task</a></div>
<section class="panel"><form class="filters" method="get"><div><label for="q">Search tasks</label><input type="search" id="q" name="q" value="<?=e($search)?>" placeholder="Find a task or note…"></div><div><label for="status-filter">Status</label><select id="status-filter" name="status"><?php foreach(['ACTIVE'=>'Active tasks','ALL'=>'All tasks','PENDING'=>'Pending','IN_PROGRESS'=>'In progress','OVERDUE'=>'Overdue','COMPLETED'=>'Completed','CANCELLED'=>'Cancelled'] as $v=>$label):?><option value="<?=$v?>" <?=$status===$v?'selected':''?>><?=$label?></option><?php endforeach;?></select></div><div><label for="category-filter">Category</label><select id="category-filter" name="category"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$c['category_id']?>" <?=$category===$c['category_id']?'selected':''?>><?=e($c['category_name'])?></option><?php endforeach;?></select></div><div><label for="sort">Sort by</label><select id="sort" name="sort"><option value="ai" <?=$sort==='ai'?'selected':''?>>AI priority</option><option value="due" <?=$sort==='due'?'selected':''?>>Deadline</option><option value="newest" <?=$sort==='newest'?'selected':''?>>Newest first</option></select></div><button class="btn secondary">Apply filters</button><?php if($search!==''||$category>0||$status!=='ACTIVE'||$sort!=='ai'):?><a class="btn secondary" href="tasks.php">Clear filters</a><?php endif;?></form>
<div class="panel-head"><p class="muted"><?=count($tasks)?> task<?=count($tasks)!==1?'s':''?><?=count($tasks)===250?' (first 250; use filters to narrow results)':''?></p><a class="link" href="assistant.php">How AI priority works <?=icon('arrow-right')?></a></div>
<?php if(!$tasks):?><div class="empty"><div class="empty-icon"><?=icon('tasks')?></div><h2>A little space for your next idea.</h2><p>No tasks match this view. Create a task or adjust your filters.</p><a class="btn primary" href="add_task.php">Create a task</a> <a class="btn secondary" href="tasks.php?status=ALL">Show all tasks</a></div><?php else:?><div class="table-wrap"><table class="task-table"><thead><tr><th scope="col">Task</th><th scope="col">Deadline</th><th scope="col">AI priority</th><th scope="col">Status</th><th scope="col">Actions</th></tr></thead><tbody>
<?php foreach($tasks as $t):$active=in_array($t['status'],['PENDING','IN_PROGRESS'],true);$over=$active&&$t['due_at']&&strtotime($t['due_at'])<time();?><tr><td data-label="Task"><a class="task-title" href="edit_task.php?id=<?=$t['task_id']?>"><strong><?=e($t['title'])?></strong></a><p class="muted task-description"><?=e(mb_strimwidth($t['description']??'',0,110,'…'))?></p><span class="pill"><?=e($t['category_name']?:'Uncategorised')?></span> <small><?=e(ucfirst(strtolower($t['importance'])))?> importance</small></td><td data-label="Deadline"><span class="<?=$over?'overdue-text':''?>"><?=e(format_datetime($t['due_at']))?></span><?php if($over):?><small class="overdue-text">Overdue</small><?php endif;?></td><td data-label="AI priority"><?php if($active):?><details><summary><span class="pill <?=e(strtolower($t['ai_priority_level']??'low'))?>"><?=round((float)$t['ai_priority_score'])?> · <?=e(ucfirst(strtolower($t['ai_priority_level']??'LOW')))?></span></summary><p class="field-help"><?=e($t['ai_reason'])?></p></details><?php else:?><span class="muted">Archived</span><?php endif;?></td><td data-label="Status"><span class="pill status-<?=e(strtolower($t['status']))?>"><?=e(status_label($t['status']))?></span></td><td data-label="Actions"><div class="actions"><a class="btn secondary small" href="edit_task.php?id=<?=$t['task_id']?>" aria-label="Edit <?=e($t['title'])?>">Edit</a>
<?php foreach($active?['complete'=>'Complete','postpone'=>'+1 day']:['reopen'=>'Reopen'] as $action=>$label):?><form method="post" action="task_action.php"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$t['task_id']?>"><?php foreach($returnFilters as $key=>$value):?><input type="hidden" name="<?=e($key)?>" value="<?=e((string)$value)?>"><?php endforeach;?><input type="hidden" name="action" value="<?=$action?>"><button class="btn secondary small" aria-label="<?=e($label.' '.$t['title'])?>"><?=$label?></button></form><?php endforeach;?>
<form method="post" action="task_action.php" data-confirm="Permanently delete this task and its reminders? This cannot be undone."><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$t['task_id']?>"><?php foreach($returnFilters as $key=>$value):?><input type="hidden" name="<?=e($key)?>" value="<?=e((string)$value)?>"><?php endforeach;?><input type="hidden" name="action" value="delete"><button class="btn danger small" aria-label="Delete <?=e($t['title'])?>"><?=icon('trash')?></button></form></div></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section></main><?php include 'includes/footer.php';?>
